function insertPeriod(schedule, newPeriod) {
  let [start, end] = newPeriod;
  const out = [];
  let i = 0;
  const n = schedule.length;

  // 1. everything that ends strictly before the new period starts
  while (i < n && schedule[i][1] < start) out.push(schedule[i++]);

  // 2. the contiguous run that overlaps or touches: absorb it
  while (i < n && schedule[i][0] <= end) {
    start = Math.min(start, schedule[i][0]);
    end = Math.max(end, schedule[i][1]);       // max, never assignment
    i++;
  }
  out.push([start, end]);

  // 3. everything after
  while (i < n) out.push(schedule[i++]);
  return out;
}
